"""Run native research Python through the existing owned backtest runner."""
from __future__ import annotations

import ast
import json
import logging
import re
import shlex
import uuid
from pathlib import Path

from src.agent.tools import BaseTool
from src.core.runner import Runner
from src.tools.path_utils import safe_path, safe_run_dir

_LIMIT = 50_000
logger = logging.getLogger(__name__)
_IMPORTS = {"__future__", "ast", "collections", "csv", "datetime", "decimal", "functools",
            "itertools", "json", "math", "numpy", "pandas", "pathlib", "re", "scipy",
            "sklearn", "statistics", "typing", "warnings"}


def validate_analysis(source: str) -> None:
    from backtest.runner import _reject_forbidden_node

    tree = ast.parse(source)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            modules = [alias.name for alias in node.names]
        elif isinstance(node, ast.ImportFrom):
            if node.level or not node.module:
                raise ValueError("relative imports are not supported")
            modules = [node.module]
        else:
            modules = []
        for module in modules:
            if module.split(".")[0] not in _IMPORTS and not any(
                module == prefix or module.startswith(prefix + ".")
                for prefix in ("src.quantlib", "src.factors", "backtest.metrics", "backtest.validation")
            ):
                raise ValueError("research imports must use the bundled numerical libraries")
        _reject_forbidden_node(node)


def command_source(command: str, workspace: Path) -> str:
    if not isinstance(command, str) or not command.strip() or len(command) > 256_000:
        raise ValueError("a bounded Python command is required")
    heredoc = re.fullmatch(r"\s*(?:python|python3|py)(?:\.exe)?\s+-\s*<<\s*['\"]?(\w+)['\"]?\s*\n(.*)\n\1\s*", command, re.S)
    if heredoc:
        return heredoc[2]
    tokens = shlex.split(command, posix=True)
    if len(tokens) < 2 or tokens[0].lower() not in {"python", "python3", "python.exe", "python3.exe", "py"}:
        raise ValueError("use python -c or python <workspace-script.py>; shell and package installation are unavailable")
    if len(tokens) == 3 and tokens[1] == "-c":
        return tokens[2]
    if len(tokens) == 2 and tokens[1].endswith(".py"):
        script = safe_path(tokens[1], str(workspace))
        if not script.is_file() or script.stat().st_size > 256_000:
            raise ValueError("a bounded workspace Python script is required")
        return script.read_text(encoding="utf-8")
    raise ValueError("only one Python script or -c expression is supported; use native file and data tools for other operations")


class _AnalysisRunner(Runner):
    def _build_runtime_env(self, run_dir, **kwargs):
        env = super()._build_runtime_env(run_dir, **kwargs)
        for key in list(env):
            if any(marker in key.upper() for marker in ("TOKEN", "API_KEY", "PASSWORD", "SECRET", "COOKIE", "PRIVATE_KEY")):
                env.pop(key)
        return env


class HostedPythonTool(BaseTool):
    name = "bash"
    description = (
        "Run Python analysis with the bundled numpy/pandas/scipy/sklearn and src.quantlib/src.factors. "
        "Use python -c '...' or write_file then python analysis.py. The working directory is the current research task. "
        "Read upstream artifacts by their supplied paths. Network access, arbitrary shell, pip, process control and broker "
        "modules are unavailable. Fetch data with native financial tools; save reports with write_file."
    )
    parameters = {"type": "object", "properties": {"command": {"type": "string"}}, "required": ["command"]}
    repeatable = True
    is_readonly = False

    def execute(self, **kwargs) -> str:
        try:
            workspace = safe_run_dir(str(kwargs.get("run_dir") or "")).resolve(strict=True)
            source = command_source(kwargs.get("command"), workspace)
            validate_analysis(source)
            work = safe_path(".mona_python/" + uuid.uuid4().hex[:16], str(workspace))
            work.mkdir(parents=True)
            script = work / "analysis.py"
            script.write_text(source, encoding="utf-8")
            entry = Path(__file__).resolve().parents[1] / "core/mona_python_entry.py"
            from src.config.paths import get_swarm_runs_dir
            read_root = workspace
            swarms = get_swarm_runs_dir().resolve()
            for parent in workspace.parents:
                if parent.name == "artifacts" and parent.parent.parent == swarms:
                    read_root = parent
                    break
            runner = _AnalysisRunner()
            result = runner.execute(entry, work, cwd=workspace, cli_args=[str(workspace), str(script), str(read_root)])
            return json.dumps({"status": "ok" if result.success else "error", "exit_code": result.exit_code,
                "stdout": result.stdout[:_LIMIT], "stderr": result.stderr[:_LIMIT],
                "output_truncated": len(result.stdout) > _LIMIT or len(result.stderr) > _LIMIT,
                "artifacts": {"stdout": str(work / "logs/runner_stdout.txt"), "stderr": str(work / "logs/runner_stderr.txt")}}, ensure_ascii=False)
        except Exception as exc:
            logger.exception("Native Python analysis failed (%s)", type(exc).__name__)
            return json.dumps({"status": "error", "error_code": "python_analysis_unavailable",
                "error_category": type(exc).__name__,
                "message": str(exc) if isinstance(exc, (SyntaxError, ValueError)) else "Python analysis did not complete; inspect the native task diagnostics."}, ensure_ascii=False)
